@Test
public void practice_numCollidedEntries_emptySet() {
    assertEquals(0, mHashSet.numCollidedEntries());
    sPoints += 1;
}

@Test
public void practice_numCollidedEntries_sixItemsTwoCollisions() {
    mHashSet.add("hello");
    mHashSet.add("hi");
    mHashSet.add("caio");
    mHashSet.add("hola");
    mHashSet.add("shalom");
    mHashSet.add("bonjour");
    assertEquals(2, mHashSet.numCollidedEntries());
    sPoints += 1;
}

@Test
public void practice_rehash_happensOnEleventhAdd() {
    String[] tenItems = { "hello", "hi", "caio", "hola", "shalom", "bonjour", "ni-hao", "aloha", "tere", "sveiki" };
    for (String s : tenItems) {
        mHashSet.add(s);
    }
    assertFalse("Pre-rehash table should still have exactly 5 bucket lines (0-4)",
        mHashSet.toRawString().contains("5:"));
    mHashSet.add("mulishani");
    assertTrue("Post-rehash table should expose at least bucket 5",
        mHashSet.toRawString().contains("5:"));
    sPoints += 1;
}
